func storeStubInstanceOf(tb assert.TB, s *partnernamingtest.StoreStub) storeStubInstance {
	tb.Helper()
	return storeStubInstance{
		Stub: s.OnTouch.MethodStub,
		Call: func() {
			_ = storeStubTouch(tb, s)
		},
	}
}

